// @ts-nocheck
/* eslint-disable */
/**
 * RelaySiteShot — ported from the Claude Design file "Relay Site Shot.dc.html".
 * Generated by scripts/dc-port/convert.mjs: the template is compiled to JSX and
 * the logic class is the design's own. Re-run the converter rather than
 * hand-editing layout; product wiring lives in the files that render this.
 */
'use client'

import React from 'react'
import {
  DCLogic,
  defineDC,
  hole,
  css,
  sty,
  list,
  hostStyle,
  href,
  frameSrc,
  asset,
  dv,
  A,
  dcNavigate,
  dcSearch,
  userName,
  userAvatar,
  holeText,
} from '@/lib/dc/runtime'

class Component extends DCLogic {
  state = { w: 800 }
  box = React.createRef()
  componentDidMount() {
    const el = this.box.current
    if (el) {
      this._ro = new ResizeObserver(([e]) => this.setState({ w: e.contentRect.width }))
      this._ro.observe(el)
    }
  }
  componentWillUnmount() {
    this._ro?.disconnect()
  }
  renderVals() {
    const W = this.props.frameW ?? 1200,
      H = this.props.frameH ?? 760,
      sc = this.state.w / W
    return {
      box: this.box,
      src: this.props.src ?? 'Relay Dashboard.dc.html?plan=pro',
      iw: W + 'px',
      ih: H + 'px',
      sc: sc.toFixed(4),
      h: Math.round(H * sc) + 'px',
      fade: this.props.fade === false ? '0' : '30%',
    }
  }
}

function template(v0, self) {
  return (
    <>
      <div
        ref={v0.box}
        style={css(
          `position:relative;width:100%;border-radius:14px;overflow:hidden;background:#151618;box-shadow:0 0 0 1px rgba(255,255,255,.09),inset 0 1px 0 rgba(255,255,255,.06),0 40px 80px -30px rgba(0,0,0,.85);height:${v0.h ?? ''}`,
        )}
      >
        {' '}
        <iframe
          src={frameSrc(v0.src)}
          title="Relay product"
          tabIndex="-1"
          loading="lazy"
          style={css(
            `position:absolute;left:0;top:0;border:0;pointer-events:none;transform-origin:0 0;width:${v0.iw ?? ''};height:${v0.ih ?? ''};transform:scale(${v0.sc ?? ''})`,
          )}
        />{' '}
        <div
          style={css(
            `position:absolute;left:0;right:0;bottom:0;height:${v0.fade ?? ''};pointer-events:none;background:linear-gradient(180deg,rgba(15,16,17,0),#0f1011)`,
          )}
        />
      </div>
    </>
  )
}

export default defineDC('Relay Site Shot', Component, template)
